// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant DAO_ADMIN = address(0x1234);

    function setUp() public { 
        c = new C(DAO_ADMIN); 
    }

    function testFuzz_property(address from, address target, bool emergency) public {
        // Only test if the initial DAO is as expected
        vm.assume(c.DAO() == DAO_ADMIN);

        // Drive the contract: call assertGovernanceApproved
        // We don't care if it reverts or not; we just want to test the state after
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", from, target, emergency)
        );

        // The general rule: DAO must never change from its initial value
        assertTrue(c.DAO() == DAO_ADMIN, "DAO changed after assertGovernanceApproved");
    }
}

